// testAccCheckComputeInstanceResetCount counts completed reset actions for a given instance.
// Reset leaves the instance RUNNING, so the operation log is the only  observableevidence that the action ran.
func testAccCheckComputeInstanceResetCount(t *testing.T, n string, want int) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[n]
		if !ok {
			return fmt.Errorf("Resource %s not found in state", n)
		}
		project := rs.Primary.Attributes["project"]
		zone := rs.Primary.Attributes["zone"]
		instanceID := rs.Primary.Attributes["instance_id"]

		config := acctest.GoogleProviderConfig(t)
		baseURL := fmt.Sprintf("%sprojects/%s/zones/%s/operations", transport_tpg.BaseUrl(tpgcompute.Product, config), project, zone)
		query := url.Values{}
		query.Set("filter", `operationType = "reset"`)

		got := 0
		for {
			res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   project,
				RawURL:    baseURL + "?" + query.Encode(),
				UserAgent: config.UserAgent,
			})
			if err != nil {
				return fmt.Errorf("error listing zone operations: %s", err)
			}

			items, _ := res["items"].([]interface{})
			for _, raw := range items {
				op, ok := raw.(map[string]interface{})
				if !ok {
					continue
				}
				if op["targetId"] == instanceID && op["status"] == "DONE" && op["error"] == nil {
					got++
				}
			}

			token, _ := res["nextPageToken"].(string)
			if token == "" {
				break
			}
			query.Set("pageToken", token)
		}
		if got != want {
			return fmt.Errorf("Expected %d completed reset actions on instance %s, got %d", want, rs.Primary.ID, got)
		}
		return nil
	}
}

