// Initial config with lifecycle trigger for after_create
func testAccComputeInstanceResetAction_basic(context map[string]interface{}, trigger string) string {
	context["trigger"] = trigger
	return acctest.Nprintf(`
resource "google_compute_instance" "test" {
  name         = "tf-test-reset-%{random_suffix}"
  machine_type = "e2-micro"
  zone         = "%{zone}"

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-13"
    }
  }

  network_interface {
    network = "default"
  }
}

action "google_compute_instance_reset" "test" {
	config {
		instance = google_compute_instance.test.self_link
		timeout = "10m"
		}
}

resource "terraform_data" "trigger" {
	input = "${google_compute_instance.test.instance_id}-%{trigger}"

	lifecycle {
	action_trigger {
		events  = [after_create, after_update]
		actions = [action.google_compute_instance_reset.test]
		}
	 }
}
`, context)
}

